  "judge": {
    "scores": {"faithfulness": 2, "non_triviality": 2, "contrastive_value": 1, "register": 2, "anchoring": 2},
    "verdict": "keep",
    "reason": "Bundle Tilaka chunk matches both claims (saṃnyāsitva-based dirt-as-ornament resolution; Tīrtha's citrāṅgī variant cited within the same chunk); orthogonal to Phase-1's Kālidāsa mṛṇālī parallel; anchoring verified via content_anchor (containment 0.375) despite pratīka mismatch.",
